import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JPasswordField;
import javax.swing.JTextField;

public class LoginPanel extends JPanel {

    private final JTextField user = new JTextField(10);
    private final JPasswordField pass = new JPasswordField(10);
    private final JButton login = new JButton("Log in");
    private final JLabel status = new JLabel("");

    public LoginPanel() {
        user.setName("user");
        pass.setName("pass");
        login.setName("login");
        status.setName("status");
        add(user);
        add(pass);
        add(login);
        add(status);
        login.addActionListener(this::onLogin);
    }

    private void onLogin(ActionEvent e) {
        // TODO: set status to "welcome <user>" or "missing input"
    }
}

