public class LoginPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            LoginPanel panel = new LoginPanel();
            java.awt.Component status = find(panel, "status");
            java.awt.Component userC = find(panel, "user");
            java.awt.Component passC = find(panel, "pass");
            java.awt.Component loginC = find(panel, "login");
            check("status label starts empty", "", textOf(status));
            boolean wired = userC instanceof javax.swing.JTextField
                    && passC instanceof javax.swing.JPasswordField
                    && loginC instanceof javax.swing.JButton;
            check("all components found by name", true, wired);
            if (wired) {
                javax.swing.JTextField user = (javax.swing.JTextField) userC;
                javax.swing.JPasswordField pass = (javax.swing.JPasswordField) passC;
                javax.swing.JButton login = (javax.swing.JButton) loginC;
                user.setText("maria");
                pass.setText("secret");
                login.doClick();
                check("both fields filled", "welcome maria", textOf(status));
                user.setText("");
                pass.setText("secret");
                login.doClick();
                check("empty user rejected", "missing input", textOf(status));
                user.setText("sam");
                pass.setText("");
                login.doClick();
                check("empty password rejected", "missing input", textOf(status));
                user.setText("sam");
                pass.setText("hunter2");
                login.doClick();
                check("login works again after a failure", "welcome sam", textOf(status));
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

